const MOTION_SPEED = 90.0
const BOMB_RATE = 0.5

@export var synced_position := Vector2()
@export var stunned: bool = false

var last_bomb_time := BOMB_RATE
var current_anim: String = ""

func _ready() -> void:
	stunned = false
	position = synced_position
	if str(name).is_valid_int():
		$"Inputs/InputsSync".set_multiplayer_authority(str(name).to_int())

func _physics_process(delta: float) -> void:
	if multiplayer.multiplayer_peer == null or str(multiplayer.get_unique_id()) == str(name):
		inputs.update()
	if multiplayer.multiplayer_peer == null or is_multiplayer_authority():
		synced_position = position
		last_bomb_time += delta
		if not stunned and is_multiplayer_authority() and inputs.bombing and last_bomb_time >= BOMB_RATE:
			last_bomb_time = 0.0
			$"../../BombSpawner".spawn([position, str(name).to_int()])
	else:
		position = synced_position
	if not stunned:
		velocity = inputs.motion * MOTION_SPEED
		move_and_slide()

	var new_anim := &"standing"
	if inputs.motion.y < 0: new_anim = &"walk_up"
	elif inputs.motion.y > 0: new_anim = &"walk_down"
	elif inputs.motion.x < 0: new_anim = &"walk_left"
	elif inputs.motion.x > 0: new_anim = &"walk_right"
	if stunned: new_anim = &"stunned"
	if new_anim != current_anim:
		current_anim = new_anim
		$anim.play(current_anim)

