@export var SPEED: float = 5.0
@export var JUMP_VELOCITY: float = 4.5
@export var enable_gravity = true

var gravity: float = 9.8
var movement_enabled: bool = true

func _ready() -> void:
	_camera = owner.get_node("%MainCamera3D")
	for input in InputMovementDic:
		var key_val = InputMovementDic[input].get("Key")
		var action_val = InputMovementDic[input].get("Action")
		var movement_input = InputEventKey.new()
		movement_input.physical_keycode = key_val
		InputMap.add_action(action_val)
		InputMap.action_add_event(action_val, movement_input)

func _physics_process(delta: float) -> void:
	if enable_gravity and not is_on_floor():
		velocity.y -= gravity * delta
	if not movement_enabled: return

	var input_dir: Vector2 = Input.get_vector("move_left", "move_right", "move_up", "move_down")
	var direction: Vector3 = (transform.basis * Vector3(input_dir.x, 0, input_dir.y)).normalized()
	if direction:
		var move_dir: Vector3 = Vector3.ZERO
		move_dir.x = direction.x
		move_dir.z = direction.z
		move_dir = move_dir.rotated(Vector3.UP, _camera.rotation.y).normalized()
		velocity.x = move_dir.x * SPEED
		velocity.z = move_dir.z * SPEED
	else:
		velocity.x = move_toward(velocity.x, 0, SPEED)
		velocity.z = move_toward(velocity.z, 0, SPEED)
	move_and_slide()

extends RigidBody3D

const ACCEL: float = 5.0
const DEACCEL: float = 20.0
const MAX_SPEED: float = 2.0
const ROT_SPEED: float = 1.0

var prev_advance: bool = false
var dying: bool = false
var rot_dir: float = 4.0

func _integrate_forces(state: PhysicsDirectBodyState3D) -> void:
	var delta := state.get_step()
	var lin_velocity := state.get_linear_velocity()
	var grav := state.get_total_gravity()
	if grav.is_zero_approx(): grav = gravity
	lin_velocity += grav * delta

	if dying:
		state.set_linear_velocity(lin_velocity)
		return

	for i in state.get_contact_count():
		var contact_collider := state.get_contact_collider_object(i)
		if contact_collider is Bullet and contact_collider.enabled:
			dying = true
			state.set_angular_velocity(-contact_normal.cross(up).normalized() * 33.0)
			return

	var advance: bool = _ray_floor.is_colliding() and not _ray_wall.is_colliding()
	var dir: Vector3 = ($Enemy/Skeleton as Node3D).get_transform().basis.z.normalized()

	if advance:
		if dir.dot(lin_velocity) < MAX_SPEED:
			lin_velocity += dir * ACCEL * delta
	else:
		if prev_advance: rot_dir = 1
		dir = Basis(up, rot_dir * ROT_SPEED * delta) * dir

	state.set_linear_velocity(lin_velocity)
	prev_advance = advance

class_name Enemy
extends RigidBody2D

const WALK_SPEED = 50

enum State { WALKING, DYING }
var _state := State.WALKING
var direction := -1

func _integrate_forces(state: PhysicsDirectBodyState2D) -> void:
	var velocity := state.get_linear_velocity()

	if _state == State.DYING:
		pass
	elif _state == State.WALKING:
		var wall_side := 0.0
		for collider_index in state.get_contact_count():
			var collider := state.get_contact_collider_object(collider_index)
			var collision_normal := state.get_contact_local_normal(collider_index)
			if collider is Bullet:
				_state = State.DYING
				break
			if collision_normal.x > 0.9: wall_side = 1.0
			elif collision_normal.x < -0.9: wall_side = -1.0
		if wall_side != 0 and wall_side != direction:
			direction = -direction
			$Sprite2D.scale.x = -direction
		velocity.x = direction * WALK_SPEED

	state.set_linear_velocity(velocity)

class_name TerrainGenerator
extends Resource

const RANDOM_BLOCK_PROBABILITY = 0.015

static func empty() -> Dictionary[Vector3i, int]:
	return {}

static func random_blocks() -> Dictionary[Vector3i, int]:
	var random_data: Dictionary[Vector3i, int] = {}
	for x in Chunk.CHUNK_SIZE:
		for y in Chunk.CHUNK_SIZE:
			for z in Chunk.CHUNK_SIZE:
				var vec := Vector3i(x, y, z)
				if randf() < RANDOM_BLOCK_PROBABILITY:
					random_data[vec] = randi() % 29 + 1
	return random_data

static func flat(chunk_position: Vector3i) -> Dictionary[Vector3i, int]:
	var data: Dictionary[Vector3i, int] = {}
	if chunk_position.y != -1: return data
	for x in Chunk.CHUNK_SIZE:
		for z in Chunk.CHUNK_SIZE:
			data[Vector3i(x, 2, z)] = 3  # Grass
			data[Vector3i(x, 1, z)] = 2  # Dirt
			data[Vector3i(x, 0, z)] = 2  # Dirt
	return data

